#!/usr/bin/env python3
"""ZOWN: make the app cross-functional.
Run from the expo/ folder:  python3 apply_cross_functional.py
All-or-nothing: every change is matched in memory first and nothing is written unless all of it matches."""
import os, sys

NEW_FILES = {
 "lib/userProfileData.js": "// lib/userProfileData.js\n//\n// One place that gathers what the app knows about a person (profile, latest\n// weight from logs/scans, goals, injuries, training schedule, food rules) so\n// the AI coach, the workout generator and the nutrition targets all read the\n// SAME facts instead of each guessing on their own. Pure functions only, so\n// they are easy to test.\nimport { getDietProfile } from './dietProfile';\n\nexport const GOAL_LABELS = {\n  lose_weight: 'Lose Weight',\n  build_muscle: 'Build Muscle',\n  improve_endurance: 'Improve Endurance',\n  stay_active: 'Stay Active',\n  train_for_race: 'Train for a Race',\n  eat_healthier: 'Eat Healthier',\n  reduce_stress: 'Reduce Stress',\n};\n\nexport const INJURY_LABELS = {\n  knee: 'Knee', shoulder: 'Shoulder', lower_back: 'Lower Back', hip: 'Hip',\n  ankle: 'Ankle', wrist: 'Wrist', elbow: 'Elbow', neck: 'Neck',\n};\n\n// Profile goal ids -> the ids the Quick Workout generator understands.\nconst QUICK_GOAL_MAP = {\n  lose_weight: 'weight_loss',\n  build_muscle: 'build_muscle',\n  improve_endurance: 'improve_endurance',\n  train_for_race: 'improve_endurance',\n  stay_active: 'general_fitness',\n  eat_healthier: 'general_fitness',\n  reduce_stress: 'improve_flexibility',\n};\n\nconst asList = (v) => (Array.isArray(v) ? v.filter((x) => typeof x === 'string') : []);\nconst num = (v) => (typeof v === 'number' && Number.isFinite(v) && v > 0 ? v : null);\nconst humanize = (id) => String(id || '').replace(/_/g, ' ');\n\n/** Goal ids the person picked in onboarding / Edit Profile (user.goals was never filled in). */\nexport function getGoalIds(user) {\n  const picked = asList(user?.fitnessMetrics?.targetGoals);\n  return picked.length ? picked : asList(user?.goals);\n}\n\n/** Goal ids converted to Quick Workout ids, no repeats. */\nexport function toQuickWorkoutGoals(user) {\n  const out = [];\n  getGoalIds(user).forEach((id) => {\n    const mapped = QUICK_GOAL_MAP[id] || (Object.values(QUICK_GOAL_MAP).includes(id) ? id : null);\n    if (mapped && !out.includes(mapped)) out.push(mapped);\n  });\n  return out;\n}\n\n/** Goal ids as readable labels for prompts. */\nexport function getGoalLabels(user) {\n  return getGoalIds(user).map((id) => GOAL_LABELS[id] || humanize(id));\n}\n\nconst timeOf = (iso) => {\n  const t = new Date(iso).getTime();\n  return Number.isNaN(t) ? null : t;\n};\n\n/**\n * Newest known weight in kg: the most recent weight log or body scan, else the\n * number saved on the profile.\n */\nexport function latestWeight({ weightLogs = [], scans = [], user = null } = {}) {\n  const candidates = [];\n  (weightLogs || []).forEach((l) => {\n    const kg = num(l?.weightKg);\n    const t = timeOf(l?.createdAtLocal);\n    if (kg && t !== null) candidates.push({ kg, t, source: 'weight log' });\n  });\n  (scans || []).forEach((s) => {\n    const kg = num(s?.weightKg);\n    const t = timeOf(s?.createdAtLocal);\n    if (kg && t !== null) candidates.push({ kg, t, source: 'body scan' });\n  });\n  if (candidates.length) {\n    candidates.sort((a, b) => b.t - a.t);\n    return { kg: candidates[0].kg, source: candidates[0].source };\n  }\n  const saved = num(user?.weightKg) || num(user?.fitnessMetrics?.weight);\n  return saved ? { kg: saved, source: 'profile' } : { kg: null, source: null };\n}\n\n/** Change in weight (kg) between the oldest and newest log in the last `days` days. */\nexport function weightTrend(weightLogs, { now = new Date(), days = 30 } = {}) {\n  const cutoff = now.getTime() - days * 86400000;\n  const pts = (weightLogs || [])\n    .map((l) => ({ kg: num(l?.weightKg), t: timeOf(l?.createdAtLocal) }))\n    .filter((p) => p.kg && p.t !== null && p.t >= cutoff && p.t <= now.getTime() + 86400000)\n    .sort((a, b) => a.t - b.t);\n  if (pts.length < 2) return null;\n  const first = pts[0];\n  const last = pts[pts.length - 1];\n  return {\n    changeKg: Math.round((last.kg - first.kg) * 10) / 10,\n    days: Math.max(1, Math.round((last.t - first.t) / 86400000)),\n    entries: pts.length,\n  };\n}\n\n/** Newest body-fat % from a scan, or null. */\nexport function latestBodyFat(scans) {\n  const withFat = (scans || [])\n    .map((s) => ({ pct: num(s?.bodyFatPercent), t: timeOf(s?.createdAtLocal) }))\n    .filter((s) => s.pct && s.t !== null)\n    .sort((a, b) => b.t - a.t);\n  return withFat.length ? withFat[0].pct : null;\n}\n\n/** Everything about the person in one plain object. Missing values are null / []. */\nexport function buildProfile({ user, weightLogs = [], scans = [] } = {}) {\n  const w = latestWeight({ weightLogs, scans, user });\n  const prefs = user?.preferences || {};\n  const metrics = user?.fitnessMetrics || {};\n  const days = Number(prefs.workoutDaysPerWeek);\n  const diet = getDietProfile(user);\n  return {\n    weightKg: w.kg,\n    weightSource: w.source,\n    targetWeightKg: num(user?.targetWeightKg),\n    heightCm: num(user?.heightCm) || num(metrics.height),\n    age: num(user?.age),\n    gender: typeof user?.gender === 'string' && user.gender ? user.gender : null,\n    activityLevel: typeof metrics.activityLevel === 'string' ? metrics.activityLevel : null,\n    fitnessLevel: user?.fitnessLevel || null,\n    goalIds: getGoalIds(user),\n    injuries: asList(metrics.injuries),\n    daysPerWeek: Number.isFinite(days) && days > 0 && days <= 7 ? days : null,\n    sessionLength: typeof prefs.preferredDuration === 'string' ? prefs.preferredDuration : null,\n    timeOfDay: typeof prefs.preferredTimeOfDay === 'string' ? prefs.preferredTimeOfDay : null,\n    bodyFatPercent: latestBodyFat(scans),\n    diet,\n  };\n}\n\n/** Flat string for the nutrition function, e.g. \"keto; allergies: peanuts; avoids: pork\". */\nexport function nutritionPreferenceText(diet) {\n  const d = diet || { dietId: 'no_preference', allergies: [], avoid: [] };\n  const parts = [];\n  if (d.dietId && d.dietId !== 'no_preference') parts.push(humanize(d.dietId));\n  if (d.allergies?.length) parts.push(`allergies (strict): ${d.allergies.map(humanize).join(', ')}`);\n  if (d.avoid?.length) parts.push(`avoids: ${d.avoid.map(humanize).join(', ')}`);\n  return parts.length ? parts.join('; ') : 'no_preference';\n}\n\n/** What the nutrition Cloud Function expects. Only real values are sent. */\nexport function profileForNutrition(profile) {\n  const p = profile || {};\n  const out = {};\n  if (p.weightKg) out.weightKg = p.weightKg;\n  if (p.targetWeightKg) out.targetWeightKg = p.targetWeightKg;\n  if (p.heightCm) out.heightCm = p.heightCm;\n  if (p.age) out.age = p.age;\n  if (p.gender) out.gender = p.gender;\n  if (p.activityLevel) out.activityLevel = humanize(p.activityLevel);\n  out.nutritionPreference = nutritionPreferenceText(p.diet);\n  return out;\n}\n\n/** What the workout Cloud Function can use. Only real values are sent. */\nexport function profileForWorkouts(profile) {\n  const p = profile || {};\n  const out = {};\n  if (p.injuries?.length) out.injuries = p.injuries.map((id) => INJURY_LABELS[id] || humanize(id));\n  if (p.weightKg) out.weightKg = p.weightKg;\n  if (p.targetWeightKg) out.targetWeightKg = p.targetWeightKg;\n  if (p.age) out.age = p.age;\n  if (p.gender) out.gender = p.gender;\n  if (p.activityLevel) out.activityLevel = humanize(p.activityLevel);\n  if (p.daysPerWeek) out.daysPerWeek = p.daysPerWeek;\n  if (p.sessionLength) out.sessionLength = p.sessionLength;\n  if (p.timeOfDay) out.timeOfDay = p.timeOfDay;\n  if (p.bodyFatPercent) out.bodyFatPercent = p.bodyFatPercent;\n  return out;\n}\n\n/** Calories and macros eaten on one local date key (YYYY-MM-DD) or the UTC key the nutrition store uses. */\nexport function dayTotals(meals, dateKeys) {\n  const keys = Array.isArray(dateKeys) ? dateKeys : [dateKeys];\n  const totals = { calories: 0, protein: 0, carbs: 0, fat: 0, foods: 0 };\n  (meals || []).forEach((m) => {\n    if (!keys.includes(m?.date)) return;\n    (m.foods || []).forEach((f) => {\n      totals.calories += Number(f?.calories) || 0;\n      totals.protein += Number(f?.protein) || 0;\n      totals.carbs += Number(f?.carbs) || 0;\n      totals.fat += Number(f?.fat) || 0;\n      totals.foods += 1;\n    });\n  });\n  ['calories', 'protein', 'carbs', 'fat'].forEach((k) => { totals[k] = Math.round(totals[k]); });\n  return totals;\n}\n\nconst kgToLb = (kg) => Math.round(kg * 2.20462);\n\n/**\n * The system message that gives the coach the person's whole picture.\n * Returns null when there is nothing to say.\n */\nexport function buildSnapshotMessage({\n  profile, weightLogs = [], goals = [], nutrition = null, upcoming = [], now = new Date(),\n} = {}) {\n  const p = profile || {};\n  const lines = [];\n\n  const body = [];\n  if (p.weightKg) body.push(`weight ${kgToLb(p.weightKg)} lb (${p.weightKg} kg, from ${p.weightSource})`);\n  if (p.targetWeightKg) body.push(`target weight ${kgToLb(p.targetWeightKg)} lb`);\n  if (p.heightCm) body.push(`height ${p.heightCm} cm`);\n  if (p.age) body.push(`age ${p.age}`);\n  if (p.gender) body.push(`gender ${p.gender}`);\n  if (p.bodyFatPercent) body.push(`latest scan body fat ${p.bodyFatPercent}%`);\n  if (body.length) lines.push(`Body: ${body.join(', ')}.`);\n\n  const trend = weightTrend(weightLogs, { now });\n  if (trend) {\n    const lb = Math.round(Math.abs(trend.changeKg) * 2.20462 * 10) / 10;\n    const dir = lb === 0 ? 'unchanged' : `${trend.changeKg > 0 ? 'up' : 'down'} ${lb} lb`;\n    lines.push(`Weight trend over ${trend.days} days (${trend.entries} logs): ${dir}.`);\n  }\n\n  const habits = [];\n  if (p.activityLevel) habits.push(`activity level ${humanize(p.activityLevel)}`);\n  if (p.daysPerWeek) habits.push(`wants to train ${p.daysPerWeek} days a week`);\n  if (p.sessionLength) habits.push(`sessions about ${p.sessionLength}`);\n  if (p.timeOfDay) habits.push(`prefers ${String(p.timeOfDay).toLowerCase()} workouts`);\n  if (habits.length) lines.push(`Training habits: ${habits.join(', ')}.`);\n\n  const open = (goals || []).filter((g) => g && !g.completed && g.title);\n  if (open.length) {\n    const txt = open.slice(0, 6).map((g) => {\n      const prog = Number.isFinite(g.target) ? ` (${g.current ?? 0}/${g.target}${g.unit ? ` ${g.unit}` : ''}${g.deadline ? `, by ${g.deadline}` : ''})` : '';\n      return `${g.title}${prog}`;\n    }).join('; ');\n    lines.push(`Active goals in the app: ${txt}.`);\n  }\n\n  if (nutrition) {\n    const g = nutrition.dailyGoals || {};\n    if (g.calories) {\n      lines.push(`Daily nutrition targets: ${g.calories} kcal, ${g.protein || '?'}g protein, ${g.carbs || '?'}g carbs, ${g.fat || '?'}g fat.`);\n    }\n    const t = nutrition.today;\n    if (t && t.foods > 0) {\n      lines.push(`Eaten so far today: ${t.calories} kcal, ${t.protein}g protein, ${t.carbs}g carbs, ${t.fat}g fat.`);\n    }\n  }\n\n  if (upcoming && upcoming.length) {\n    lines.push(`Already on their calendar: ${upcoming.slice(0, 6).map((e) => `${e.title} (${e.when})`).join('; ')}. Do not double-book these times.`);\n  }\n\n  if (!lines.length) return null;\n  const header = 'More about this user, from their real app data. Use it to personalise plans (pick exercises that fit their injuries, set calories and protein from their weight and goal, fit sessions to their schedule). Only cite numbers listed here.';\n  return { role: 'system', content: [header, ...lines].join(' ') };\n}\n",
 "services/coachSnapshotService.js": "// services/coachSnapshotService.js\n//\n// Reads the app's stores (weight logs, body scans, goals, nutrition,\n// calendar) at the moment a coach message is sent and turns them into the\n// system message built by lib/userProfileData.js. Read fresh each time so\n// the coach never works from numbers that were changed after the screen\n// opened. Any problem reading a store just leaves that part out.\nimport { useWeightLogStore } from '../store/weightLogStore';\nimport { useBodyCompositionStore } from '../store/bodyCompositionStore';\nimport { useGoalsStore } from '../store/goalsStore';\nimport { useNutritionStore } from '../store/nutritionStore';\nimport { useScheduleStore } from '../store/scheduleStore';\nimport { upcomingEvents } from '../lib/scheduleUtils';\nimport { formatEventWhen } from '../lib/coachActions';\nimport { buildProfile, buildSnapshotMessage, dayTotals } from '../lib/userProfileData';\n\nconst safe = (fn, fallback) => {\n  try { return fn(); } catch (e) { console.warn('[coachSnapshot] skipped:', e?.message); return fallback; }\n};\n\nexport function loadSnapshotSources(uid) {\n  return Promise.all([\n    useWeightLogStore.getState().loadLogs(uid),\n    useBodyCompositionStore.getState().loadScans(uid),\n    useGoalsStore.getState().loadGoals(uid),\n  ]);\n}\n\nexport function getProfileFromStores(user) {\n  const weightLogs = safe(() => useWeightLogStore.getState().logs, []);\n  const scans = safe(() => useBodyCompositionStore.getState().scans, []);\n  return buildProfile({ user, weightLogs, scans });\n}\n\nexport function buildSnapshotFromStores(user, now = new Date()) {\n  const weightLogs = safe(() => useWeightLogStore.getState().logs, []);\n  const scans = safe(() => useBodyCompositionStore.getState().scans, []);\n  const goals = safe(() => useGoalsStore.getState().goals, []);\n  const profile = buildProfile({ user, weightLogs, scans });\n  const nutrition = safe(() => {\n    const { meals, dailyGoals } = useNutritionStore.getState();\n    // The nutrition store keys days by the UTC date; include the local date too.\n    const local = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;\n    return { dailyGoals, today: dayTotals(meals, [now.toISOString().slice(0, 10), local]) };\n  }, null);\n  const upcoming = safe(\n    () => upcomingEvents(useScheduleStore.getState().events, now, 6).map((e) => ({ title: e.title, when: formatEventWhen(e.start) })),\n    []\n  );\n  return buildSnapshotMessage({ profile, weightLogs, goals, nutrition, upcoming, now });\n}\n",
 "__tests__/userProfileData.test.js": "import {\n  getGoalIds, toQuickWorkoutGoals, getGoalLabels, latestWeight, weightTrend, buildProfile,\n  nutritionPreferenceText, profileForNutrition, profileForWorkouts, dayTotals, buildSnapshotMessage,\n} from '../lib/userProfileData';\nimport { normalizeActions, describeActions, buildQuestion, buildActionInstructions } from '../lib/coachActions';\n\nconst user = {\n  fitnessLevel: 'intermediate', heightCm: 180, weightKg: 90, age: 30, gender: 'Male', targetWeightKg: 82,\n  fitnessMetrics: {\n    targetGoals: ['lose_weight', 'train_for_race', 'build_muscle'], injuries: ['knee', 'lower_back'],\n    activityLevel: 'moderately_active', nutritionPreference: 'keto', foodAllergies: ['peanut'], avoidFoods: [],\n  },\n  preferences: { workoutDaysPerWeek: 4, preferredDuration: '45min', preferredTimeOfDay: 'Morning' },\n};\nconst NOW = new Date(2026, 9, 7, 12, 0);\nconst iso = (d) => new Date(2026, 9, d, 8).toISOString();\n\ndescribe('goals', () => {\n  it('reads goals from fitnessMetrics.targetGoals', () => {\n    expect(getGoalIds(user)).toEqual(['lose_weight', 'train_for_race', 'build_muscle']);\n    expect(getGoalLabels(user)).toEqual(['Lose Weight', 'Train for a Race', 'Build Muscle']);\n  });\n  it('maps them to quick workout goals without repeats', () => {\n    expect(toQuickWorkoutGoals(user)).toEqual(['weight_loss', 'improve_endurance', 'build_muscle']);\n  });\n  it('handles a user with nothing', () => {\n    expect(getGoalIds({})).toEqual([]);\n    expect(toQuickWorkoutGoals(null)).toEqual([]);\n  });\n});\n\ndescribe('weight', () => {\n  it('uses the newest of logs and scans, else the profile', () => {\n    const logs = [{ weightKg: 88, createdAtLocal: iso(1) }, { weightKg: 86.5, createdAtLocal: iso(5) }];\n    const scans = [{ weightKg: 87, createdAtLocal: iso(3) }];\n    expect(latestWeight({ weightLogs: logs, scans, user })).toEqual({ kg: 86.5, source: 'weight log' });\n    expect(latestWeight({ weightLogs: [{ weightKg: 88, createdAtLocal: iso(1) }], scans, user })).toEqual({ kg: 87, source: 'body scan' });\n    expect(latestWeight({ user })).toEqual({ kg: 90, source: 'profile' });\n    expect(latestWeight({})).toEqual({ kg: null, source: null });\n  });\n  it('ignores junk entries', () => {\n    expect(latestWeight({ weightLogs: [{ weightKg: 'x', createdAtLocal: 'nope' }], user }).source).toBe('profile');\n  });\n  it('computes a trend only with two or more recent logs', () => {\n    const logs = [{ weightKg: 90, createdAtLocal: iso(1) }, { weightKg: 88.5, createdAtLocal: iso(6) }];\n    expect(weightTrend(logs, { now: NOW })).toEqual({ changeKg: -1.5, days: 5, entries: 2 });\n    expect(weightTrend([logs[0]], { now: NOW })).toBeNull();\n  });\n});\n\ndescribe('profile', () => {\n  const profile = buildProfile({ user, weightLogs: [{ weightKg: 88, createdAtLocal: iso(5) }], scans: [{ bodyFatPercent: 21, createdAtLocal: iso(2) }] });\n  it('collects the facts', () => {\n    expect(profile).toMatchObject({ weightKg: 88, heightCm: 180, age: 30, daysPerWeek: 4, bodyFatPercent: 21, injuries: ['knee', 'lower_back'] });\n  });\n  it('builds the nutrition input with real values and the diet text', () => {\n    const n = profileForNutrition(profile);\n    expect(n).toMatchObject({ weightKg: 88, targetWeightKg: 82, heightCm: 180, age: 30, gender: 'Male', activityLevel: 'moderately active' });\n    expect(n.nutritionPreference).toContain('keto');\n    expect(n.nutritionPreference).toContain('allergies (strict)');\n  });\n  it('builds the workout input with injuries as words and no undefined fields', () => {\n    const w = profileForWorkouts(profile);\n    expect(w.injuries).toEqual(['Knee', 'Lower Back']);\n    expect(w.daysPerWeek).toBe(4);\n    expect(Object.values(w).every((v) => v !== undefined)).toBe(true);\n    expect(profileForWorkouts(buildProfile({ user: {} }))).toEqual({});\n  });\n  it('says no_preference when no diet is set', () => {\n    expect(nutritionPreferenceText(null)).toBe('no_preference');\n  });\n});\n\ndescribe('dayTotals', () => {\n  it('adds up foods for the matching date keys only', () => {\n    const meals = [\n      { date: '2026-10-07', foods: [{ calories: 300, protein: 20, carbs: 30, fat: 10 }, { calories: 100 }] },\n      { date: '2026-10-06', foods: [{ calories: 999 }] },\n    ];\n    expect(dayTotals(meals, ['2026-10-07'])).toEqual({ calories: 400, protein: 20, carbs: 30, fat: 10, foods: 2 });\n  });\n});\n\ndescribe('snapshot message', () => {\n  it('is null with nothing to say and rich with data', () => {\n    expect(buildSnapshotMessage({ profile: buildProfile({ user: {} }) })).toBeNull();\n    const logs = [{ weightKg: 90, createdAtLocal: iso(1) }, { weightKg: 88, createdAtLocal: iso(6) }];\n    const msg = buildSnapshotMessage({\n      profile: buildProfile({ user, weightLogs: logs }), weightLogs: logs, now: NOW,\n      goals: [{ title: 'Bench 225', current: 185, target: 225, unit: 'lb' }, { title: 'Done', completed: true }],\n      nutrition: { dailyGoals: { calories: 2200, protein: 180, carbs: 200, fat: 70 }, today: { calories: 800, protein: 50, carbs: 70, fat: 20, foods: 3 } },\n      upcoming: [{ title: 'Leg Day', when: 'Thu Oct 8, 7:00 AM' }],\n    });\n    expect(msg.role).toBe('system');\n    expect(msg.content).toContain('weight 194 lb');\n    expect(msg.content).toContain('down 4.4 lb');\n    expect(msg.content).toContain('Bench 225 (185/225 lb)');\n    expect(msg.content).not.toContain('Done');\n    expect(msg.content).toContain('wants to train 4 days a week');\n    expect(msg.content).toContain('2200 kcal');\n    expect(msg.content).toContain('Eaten so far today: 800 kcal');\n    expect(msg.content).toContain('Leg Day');\n  });\n});\n\ndescribe('coach goal action', () => {\n  it('validates goals and tells the model about them', () => {\n    expect(buildActionInstructions(NOW)).toContain('\"type\":\"goal\"');\n    const { actions, dropped } = normalizeActions([{ type: 'goal', goals: [\n      { title: ' Bench press 225 lb ', target: 225, unit: 'lb', current: 185, deadline: '2026-12-31' },\n      { title: 'Past', target: 5, deadline: '2020-01-01' },\n      { title: 'No target' },\n      { target: 10 },\n      'junk',\n    ] }], { now: NOW, user });\n    expect(dropped).toBe(3);\n    expect(actions).toHaveLength(1);\n    expect(actions[0].goals[0]).toEqual({ title: 'Bench press 225 lb', target: 225, unit: 'lb', current: 185, deadline: '2026-12-31' });\n    expect(actions[0].goals[1]).toEqual({ title: 'Past', target: 5, unit: '', current: 0, deadline: null });\n    expect(Object.values(actions[0].goals[1]).every((v) => v !== undefined)).toBe(true);\n    expect(describeActions(actions)[0]).toContain('Add 2 goals to Progress');\n    expect(buildQuestion(actions)).toContain('goal');\n  });\n  it('caps at five goals', () => {\n    const goals = Array.from({ length: 9 }, (_, i) => ({ title: `G${i}`, target: 10 }));\n    expect(normalizeActions([{ type: 'goal', goals }], { now: NOW }).actions[0].goals).toHaveLength(5);\n  });\n});\n"
}

